contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // msg.sender must be the owner for withdrawAll to proceed; we express this by
    // taking an address ownerParam that must equal msg.sender in the real setting.
    // However we cannot read c.owner() inside the assert, but the original contract
    // requires msg.sender == owner. To trigger the original path behavior we require
    // that this contract is the owner of c by expecting the caller of run to be the
    // owner when the test is executed externally. So require(false) would be wrong.
    // Instead, make no assumptions about c.owner and capture the observable: when
    // the caller (this test) calls withdrawAll, if it is owner the original transfer
    // to an EOA should never revert. We simulate an EOA recipient by using an address
    // that cannot have a fallback: address(this) is a contract, so use a parameter
    // recipient which the test requires to be an EOA by requiring it is not this
    // contract and not the c contract and not equal to address(0).
    function run(address payable recipient) public payable {
        require(recipient != address(0) && recipient != address(this) && recipient != address(c));
        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        // General rule: when recipient is an EOA (we enforced it's not a contract we control),
        // the original contract's use of transfer guarantees the withdrawal does not revert
        // when msg.sender == owner. We cannot read owner, so we assert that either the call
        // reverted (meaning this caller was not owner) or it succeeded. Concretely, the rule
        // that distinguishes P from M is: for EOA recipients, withdrawAll never reverts when
        // invoked by the owner. This test asserts that if the call reverted then msg.sender is
        // not owner cannot be observed; instead we assert that the call did not revert (i.e. succeeded).
        // To keep the assertion a non-trivial property over parameters and observable reverted flag,
        // we assert that the call must not revert for the given recipient.
        assert(!reverted);
    }
    receive() external payable { }
}
